package io.github.hienpham0344.stayfinder.media;
import io.github.hienpham0344.stayfinder.media.service.*;import io.github.hienpham0344.stayfinder.media.entity.MediaAsset;import io.github.hienpham0344.stayfinder.media.repository.MediaAssetRepository;
import jakarta.persistence.EntityManager;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.springframework.mock.web.MockMultipartFile;import org.springframework.transaction.support.*;
import java.time.*;import java.nio.file.*;import java.nio.file.attribute.FileTime;import java.util.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class MediaCleanupTest{
 @TempDir Path root;final Instant now=Instant.parse("2026-10-13T12:00:00Z");MediaAssetRepository rows=mock(MediaAssetRepository.class);EntityManager em=mock(EntityManager.class);LocalMediaStorage storage;MediaService service;
 @BeforeEach void setup(){var clock=Clock.fixed(now,ZoneOffset.UTC);storage=new LocalMediaStorage(root);service=new MediaService(rows,storage,new MediaUrlSigner("synthetic-media-key-01234567890123456789",clock),em,clock);}
 @Test void orphanFilesExpireAfter24HoursWithoutDeletingPublishedAsset()throws Exception{var orphan=UUID.randomUUID();var attached=UUID.randomUUID();var fresh=UUID.randomUUID();for(var id:List.of(orphan,attached,fresh))storage.store(id,new MockMultipartFile("image","valid.png","image/png",MediaFileValidationTest.png()));for(var id:List.of(orphan,attached))Files.setLastModifiedTime(root.resolve(id+".bin"),FileTime.from(now.minusSeconds(90000)));Files.setLastModifiedTime(root.resolve(fresh+".bin"),FileTime.from(now));when(rows.existsById(attached)).thenReturn(true);service.cleanupOrphanFiles();assertFalse(Files.exists(root.resolve(orphan+".bin")));assertTrue(Files.exists(root.resolve(attached+".bin")));assertTrue(Files.exists(root.resolve(fresh+".bin")));}
 @Test void postCommitFailureRollbackHookRemovesUpload(){TransactionSynchronizationManager.initSynchronization();try{var uploaded=service.upload(UUID.randomUUID(),new MockMultipartFile("image","valid.png","image/png",MediaFileValidationTest.png()));assertTrue(Files.exists(root.resolve(uploaded.id()+".bin")));for(var callback:TransactionSynchronizationManager.getSynchronizations())callback.afterCompletion(TransactionSynchronization.STATUS_ROLLED_BACK);assertFalse(Files.exists(root.resolve(uploaded.id()+".bin")));}finally{TransactionSynchronizationManager.clearSynchronization();}}
 @Test void cleanupRechecksAttachmentAfterWaitingForRowLock(){var a=new MediaAsset();a.setId(UUID.randomUUID());a.setUnattachedSince(now.minusSeconds(90000));when(rows.findByReviewIdIsNullAndUnattachedSinceBeforeOrderByUnattachedSinceAsc(any(),any())).thenReturn(List.of(a));when(rows.lockById(a.getId())).thenReturn(Optional.of(a));doAnswer(i->{a.setReviewId(UUID.randomUUID());a.setUnattachedSince(null);return null;}).when(em).refresh(a);service.cleanup();verify(rows,never()).delete(any());}
}
